class Solution:
    def expand(self, s: str) -> List[str]:
        groups = []
        i = 0
        while i < len(s):
            if s[i] == '{':
                j = s.index('}', i)
                groups.append(sorted(s[i+1:j].split(',')))
                i = j + 1
            else:
                groups.append([s[i]])
                i += 1
        res = []
        def bt(idx, path):
            if idx == len(groups):
                res.append(''.join(path))
                return
            for c in groups[idx]:
                bt(idx + 1, path + [c])
        bt(0, [])
        return res

class Solution:
    def confusingNumberII(self, n: int) -> int:
        mapping = {0:0, 1:1, 6:9, 8:8, 9:6}
        digits = [0, 1, 6, 8, 9]
        self.count = 0
        def is_confusing(num):
            src = num
            rotated = 0
            while num > 0:
                rotated = rotated * 10 + mapping[num % 10]
                num //= 10
            return rotated != src
        def bt(cur):
            if cur > n:
                return
            if cur != 0 and is_confusing(cur):
                self.count += 1
            for d in digits:
                nxt = cur * 10 + d
                if nxt == 0:
                    continue
                if nxt > n:
                    break
                bt(nxt)
        bt(0)
        return self.count

class Solution:
    def duplicateZeros(self, arr: List[int]) -> None:
        n = len(arr)
        zeros = arr.count(0)
        for i in range(n - 1, -1, -1):
            if arr[i] == 0:
                zeros -= 1
                if i + zeros + 1 < n:
                    arr[i + zeros + 1] = 0
            if i + zeros < n:
                arr[i + zeros] = arr[i]

class Solution:
    def largestValsFromLabels(self, values: List[int], labels: List[int], numWanted: int, useLimit: int) -> int:
        from collections import Counter
        items = sorted(zip(values, labels), reverse=True)
        label_count = Counter()
        res = 0
        chosen = 0
        for val, label in items:
            if chosen >= numWanted:
