class Solution:
    def braceExpansionII(self, expression: str) -> List[str]:
        def parse(expr, i):
            groups = [[{''}]]
            while i < len(expr):
                if expr[i] == '{':
                    i, sub = parse(expr, i + 1)
                    groups[-1].append(sub)
                elif expr[i] == '}':
                    break
                elif expr[i] == ',':
                    groups.append([{''}])
                    i += 1
                    continue
                else:
                    groups[-1].append({expr[i]})
                i += 1
            result = set()
            for group in groups:
                cur = {''}
                for s in group:
                    cur = {a + b for a in cur for b in s}
                result |= cur
            return i + 1, result
        _, res = parse(expression, 0)
        return sorted(res)

class Solution:
    def twoSumLessThanK(self, nums: List[int], k: int) -> int:
        nums.sort()
        lo, hi = 0, len(nums) - 1
        res = -1
        while lo < hi:
            s = nums[lo] + nums[hi]
            if s < k:
                res = max(res, s)
                lo += 1
            else:
                hi -= 1
        return res

class Solution:
    def numKLenSubstrNoRepeats(self, s: str, k: int) -> int:
        if k > 26:
            return 0
        from collections import Counter
        cnt = Counter()
        res = 0
        for i, c in enumerate(s):
            cnt[c] += 1
            if i >= k:
                left = s[i - k]
                cnt[left] -= 1
                if cnt[left] == 0:
                    del cnt[left]
            if i >= k - 1 and len(cnt) == k:
                res += 1
        return res

class Solution:
    def maximumMinimumPath(self, grid: List[List[int]]) -> int:
        import heapq
        m, n = len(grid), len(grid[0])
        heap = [(-grid[0][0], 0, 0)]
        visited = [[False]*n for _ in range(m)]
        visited[0][0] = True
        while heap:
            val, r, c = heapq.heappop(heap)
            if r == m-1 and c == n-1:
                return -val
            for dr, dc in [(0,1),(0,-1),(1,0),(-1,0)]:
                nr, nc = r+dr, c+dc
                if 0<=nr<m and 0<=nc<n and not visited[nr][nc]:
                    visited[nr][nc] = True
                    heapq.heappush(heap, (max(val, -grid[nr][nc]), nr, nc))
        return -1

class Solution:
    def minHeightShelves(self, books: List[List[int]], shelfWidth: int) -> int:
        n = len(books)
        dp = [float('inf')] * (n + 1)
        dp[0] = 0
        for i in range(1, n + 1):
            w = 0
            h = 0
            for j in range(i, 0, -1):
                w += books[j-1][0]
                if w > shelfWidth:
                    break
                h = max(h, books[j-1][1])
                dp[i] = min(dp[i], dp[j-1] + h)
        return dp[n]

class Solution:
    def parseBoolExpr(self, expression: str) -> bool:
        stack = []
        for c in expression:
            if c == ',':
                continue
            elif c == ')':
                operands = []
                while stack[-1] != '(':
                    operands.append(stack.pop())
                stack.pop()  # remove '('
                op = stack.pop()
                if op == '!':
                    stack.append('t' if operands[0] == 'f' else 'f')
                elif op == '&':
                    stack.append('f' if 'f' in operands else 't')
                elif op == '|':
                    stack.append('t' if 't' in operands else 'f')
            else:
                stack.append(c)
        return stack[0] == 't'

