class Solution:
    def lcaDeepestLeaves(self, root):
        def dfs(node):
            if not node:
                return None, 0
            left, ld = dfs(node.left)
            right, rd = dfs(node.right)
            if ld == rd:
                return node, ld + 1
            elif ld > rd:
                return left, ld + 1
            else:
                return right, rd + 1
        return dfs(root)[0]

class Solution:
    def longestWPI(self, hours):
        prefix = 0
        first = {}
        ans = 0
        for i, h in enumerate(hours):
            prefix += 1 if h > 8 else -1
            if prefix > 0:
                ans = i + 1
            else:
                if prefix - 1 in first:
                    ans = max(ans, i - first[prefix - 1])
                if prefix not in first:
                    first[prefix] = i
        return ans

class Solution:
    def smallestSufficientTeam(self, req_skills, people):
        n = len(req_skills)
        skill_idx = {s: i for i, s in enumerate(req_skills)}
        target = (1 << n) - 1
        dp = {0: []}
        for i, p in enumerate(people):
            mask = 0
            for s in p:
                if s in skill_idx:
                    mask |= 1 << skill_idx[s]
            for state, team in list(dp.items()):
                new_state = state | mask
                if new_state not in dp or len(dp[new_state]) > len(team) + 1:
                    dp[new_state] = team + [i]
        return dp[target]

