class Solution:
    def shortestAlternatingPaths(self, n, redEdges, blueEdges):
        from collections import defaultdict, deque
        graph = defaultdict(list)
        for u, v in redEdges:
            graph[(u, 0)].append((v, 1))
        for u, v in blueEdges:
            graph[(u, 1)].append((v, 0))
        ans = [-1] * n
        ans[0] = 0
        visited = set()
        q = deque([(0, 0, 0), (0, 1, 0)])  # node, color, dist
        visited.add((0, 0))
        visited.add((0, 1))
        while q:
            node, color, dist = q.popleft()
            for nei, nc in graph[(node, color)]:
                if (nei, nc) not in visited:
                    visited.add((nei, nc))
                    if ans[nei] == -1:
                        ans[nei] = dist + 1
                    q.append((nei, nc, dist + 1))
        return ans

class Solution:
    def mctFromLeafValues(self, arr):
        stack = [float('inf')]
        res = 0
        for x in arr:
            while stack[-1] <= x:
                mid = stack.pop()
                res += mid * min(stack[-1], x)
            stack.append(x)
