class Solution:
    def minimumCost(self, n, connections):
        parent = list(range(n + 1))
        def find(x):
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x
        connections.sort(key=lambda x: x[2])
        cost = 0
        edges = 0
        for u, v, w in connections:
            pu, pv = find(u), find(v)
            if pu != pv:
                parent[pu] = pv
                cost += w
                edges += 1
        return cost if edges == n - 1 else -1

class Solution:
    def minimumSemesters(self, n, relations):
        from collections import defaultdict, deque
        graph = defaultdict(list)
        indegree = [0] * (n + 1)
        for u, v in relations:
            graph[u].append(v)
            indegree[v] += 1
        q = deque([i for i in range(1, n+1) if indegree[i] == 0])
        semesters = 0
        taken = 0
        while q:
            semesters += 1
            for _ in range(len(q)):
                node = q.popleft()
                taken += 1
                for nei in graph[node]:
                    indegree[nei] -= 1
                    if indegree[nei] == 0:
                        q.append(nei)
        return semesters if taken == n else -1

class Solution:
    def tribonacci(self, n: int) -> int:
        if n == 0: return 0
        if n <= 2: return 1
        a, b, c = 0, 1, 1
        for _ in range(n - 2):
            a, b, c = b, c, a + b + c
        return c

class Solution:
    def alphabetBoardPath(self, target: str) -> str:
        res = []
        r, c = 0, 0
        for ch in target:
            idx = ord(ch) - ord('a')
            tr, tc = idx // 5, idx % 5
            # Move up/left before down/right to avoid going out of bounds at 'z'
            if tr < r:
                res.append('U' * (r - tr))
            if tc < c:
                res.append('L' * (c - tc))
            if tr > r:
                res.append('D' * (tr - r))
            if tc > c:
                res.append('R' * (tc - c))
            res.append('!')
            r, c = tr, tc
        return ''.join(res)

class Solution:
    def largest1BorderedSquare(self, grid):
        m, n = len(grid), len(grid[0])
        left = [[0]*n for _ in range(m)]
        top = [[0]*n for _ in range(m)]
        for i in range(m):
            for j in range(n):
                if grid[i][j]:
                    left[i][j] = (left[i][j-1] if j > 0 else 0) + 1
                    top[i][j] = (top[i-1][j] if i > 0 else 0) + 1
        for side in range(min(m, n), 0, -1):
            for i in range(m - side + 1):
                for j in range(n - side + 1):
                    if (left[i][j+side-1] >= side and
                        left[i+side-1][j+side-1] >= side and
                        top[i+side-1][j] >= side and
                        top[i+side-1][j+side-1] >= side):
                        return side * side
        return 0

class Solution:
    def stoneGameII(self, piles):
        from functools import lru_cache
        n = len(piles)
        suffix = [0] * (n + 1)
        for i in range(n - 1, -1, -1):
            suffix[i] = suffix[i + 1] + piles[i]
        @lru_cache(maxsize=None)
        def dp(i, M):
            if i >= n:
                return 0
            if i + 2 * M >= n:
                return suffix[i]
            res = 0
            for x in range(1, 2 * M + 1):
                res = max(res, suffix[i] - dp(i + x, max(M, x)))
            return res
        return dp(0, 1)
